#!/usr/bin/env bash
set -Eeuo pipefail

STAMP="$(date +%Y%m%d-%H%M%S)"

CTR="${TSP_BUILDER:-openmw_builder}"
SRC="/root/openmw-0.51-tsp-src"
BUILD="/root/openmw-0.51-tsp-build"
BUILT_BIN="$BUILD/openmw"
SRC_BACKUP="$SRC/.tsp-051-source-backups/visgrid-v17-pvs-$STAMP"

ROOT="/mnt/SDCARD/data/ports/openmw51"
BIN="$ROOT/bin/openmw-0.51"
MOD="$ROOT/mods/TSPInteriorVisGrid"
LUA="$MOD/scripts/TSPInteriorVisGrid/visgrid.lua"
TOPO="$MOD/scripts/TSPInteriorVisGrid/topology.lua"

PKG="$HOME/Downloads/openmw51-visgrid-v17-navmesh-pvs-$STAMP"
LOG="$PKG/install.log"

V16_SHA="cb2525a5b27cfdf31701ee6570cb05b6ac9468a913b320cbac589da263de245e"
V17_SHA="299c6cf709a029adf02c25e52155c71b39b5ba2e32c4bdc7b1c4f34d9a9081b3"
TOPO_SHA="24a6989dacc1149a2a3895da371e56e52d370348d01ea0a5403f4e20755bef6b"
BASE_BIN_SHA="c3641748830e0f6752bc87daa111c05f7169003d78c75aba4e303b81598d6473"
PATCHER_SHA="1551340676fcf97077e4545ede2c44732bac296e9ccd68057d2e21b36179c410"

mkdir -p "$PKG/source" "$PKG/device-backup"

# Existing old device.env may still be useful for the IP, but all NEW helpers
# and outputs live directly in ~/Downloads.
if [ -f "$HOME/Downloads/visgrid-tools/device.env" ]; then
    # shellcheck disable=SC1091
    . "$HOME/Downloads/visgrid-tools/device.env" || true
fi
if [ -n "${TSP_DEV:-}" ]; then
    DEV="$TSP_DEV"
elif [ -n "${TSP_IP:-}" ]; then
    DEV="root@$TSP_IP"
else
    DEV="root@192.168.1.25"
fi
SSH=(-o BatchMode=yes -o ConnectTimeout=8)

PATCH_STARTED=0
PATCH_NEW=0
BUILD_OK=0
DEPLOY_STARTED=0
REMOTE_BACKUP=""
BIN_SHA_BEFORE=""
LUA_SHA_BEFORE=""
TOPO_SHA_BEFORE=""
NEW_BIN_SHA=""

restore_source() {
    set +e
    if [ -d "$SRC_BACKUP" ]; then
        echo "Restoring exact pre-V17 source from verified backup..."
        docker exec "$CTR" bash -lc "
          set -e
          B='$SRC_BACKUP'
          S='$SRC'
          for f in             apps/openmw/mwrender/interiorvisibility.hpp             apps/openmw/mwrender/interiorvisibility.cpp             apps/openmw/mwrender/animation.cpp             apps/openmw/mwlua/camerabindings.cpp
          do
            test -s \"\$B/\$f\"
            cp -p \"\$B/\$f\" \"\$S/\$f\"
          done
        "
    fi
}

rollback_device() {
    set +e
    [ -n "$REMOTE_BACKUP" ] || return 1
    echo "Attempting automatic device rollback..."
    ssh "${SSH[@]}" "$DEV" "
      set -e
      test -s '$REMOTE_BACKUP/openmw-0.51.before-v17'
      test -s '$REMOTE_BACKUP/visgrid.lua.before-v17'
      cp -p '$REMOTE_BACKUP/openmw-0.51.before-v17' '$BIN'
      cp -p '$REMOTE_BACKUP/visgrid.lua.before-v17' '$LUA'
      chmod +x '$BIN'
      sync
    "
}

on_error() {
    rc=$?
    line=$1
    cmd=$2
    trap - ERR
    set +e

    if [ "$DEPLOY_STARTED" = 1 ]; then
        rollback_device || true
    fi
    if [ "$PATCH_NEW" = 1 ] && [ "$BUILD_OK" != 1 ]; then
        restore_source || true
    fi

    {
        echo
        echo "=================================================================="
        echo "VISGRID V17 PVS STOPPED SAFELY"
        echo "=================================================================="
        echo "Date: $(date)"
        echo "Exit code: $rc"
        echo "Line: $line"
        echo "Command: $cmd"
        echo
        [ -f "$LOG" ] && {
            echo "----- install.log tail -----"
            tail -220 "$LOG" || true
        }
        echo
        [ -f "$PKG/build.log" ] && {
            echo "----- build.log tail -----"
            tail -180 "$PKG/build.log" || true
        }
        echo
        echo "Package preserved:"
        echo "  $PKG"
        [ -n "$REMOTE_BACKUP" ] && echo "Device backup: $REMOTE_BACKUP"
        [ -d "$SRC_BACKUP" ] && echo "Source backup: $SRC_BACKUP"
        echo "=================================================================="
    } | tee "$PKG/STOPPED_ERROR.txt"

    exit "$rc"
}
trap 'on_error "$LINENO" "$BASH_COMMAND"' ERR
exec > >(tee "$LOG") 2>&1

echo "=================================================================="
echo "OPENMW 0.51 TSP — VISGRID V17 NAVMESH STRUCTURAL PVS"
echo "=================================================================="
echo
echo "V17 adds a conservative C++ structural pre-culler in FRONT of the"
echo "existing 8x5 VISGRID curtain."
echo
echo "Prototype policy:"
echo "  - immutable ESM::Static roots only"
echo "  - current floor stays fully eligible"
echo "  - unrelated floors may be rejected before LightList/state traversal"
echo "  - staircase connector enables both endpoint floors"
echo "  - mapped doorway into large_open pre-opens a 3x7 ray/fog wedge"
echo "  - mapped ordinary doors pre-open a 3x5 wedge"
echo "  - live rays remain final local depth authority"
echo "  - V16 250 padding reverted to 350"
echo "  - six-second load-safe hold preserved"
echo

command -v docker >/dev/null
command -v ssh >/dev/null
command -v scp >/dev/null
command -v base64 >/dev/null
command -v python3 >/dev/null

echo "===== 1/10 WRITE + VERIFY EXACT V17 PAYLOADS ====="

