aW9yVG9wb2xvZ3lQdnMiXScsCiAgICAgICAgJ291dFsicHZzQ3VsbGVkIl0nLAogICAgXSwKfQpm
b3IgcmVsLCBuZWVkbGVzIGluIHBvc3QuaXRlbXMoKToKICAgIHR4dCA9IHBhdGhzW3JlbF0ucmVh
ZF90ZXh0KGVycm9ycz0icmVwbGFjZSIpCiAgICBmb3IgbmVlZGxlIGluIG5lZWRsZXM6CiAgICAg
ICAgaWYgbmVlZGxlIG5vdCBpbiB0eHQ6CiAgICAgICAgICAgIHJhaXNlIFN5c3RlbUV4aXQoZiJF
