U09VUkNFX1NUQVRFPVYxN19QQVRDSEVEIikKcHJpbnQoZiJCQUNLVVBfRElSPXtCQUNLVVB9IikK
Zm9yIHJlbCBpbiBUQVJHRVRTOgogICAgcHJpbnQoZiJQT1NUX1NIQSB7c2hhKHBhdGhzW3JlbF0p
fSB7cmVsfSIpCg==
EOF_PATCHER_B64
base64 -d "$PKG/tsp_patch_visgrid_v17_pvs.py.b64" > "$PKG/tsp_patch_visgrid_v17_pvs.py"
rm -f "$PKG/tsp_patch_visgrid_v17_pvs.py.b64"
chmod +x "$PKG/tsp_patch_visgrid_v17_pvs.py"

test "$(sha256sum "$PKG/visgrid-v17.lua" | awk '{print $1}')" = "$V17_SHA"
test "$(sha256sum "$PKG/tsp_patch_visgrid_v17_pvs.py" | awk '{print $1}')" = "$PATCHER_SHA"
grep -Fq 'TSP_VISGRID_LUA_V17_NAVMESH_PVS' "$PKG/visgrid-v17.lua"
grep -Fq 'POST_LOAD_ARM_DELAY = 6.0' "$PKG/visgrid-v17.lua"
grep -Fq 'TSP_VISGRID_V17_LOADSAFE_6S' "$PKG/visgrid-v17.lua"
! grep -Fq 'v16TightPadding = 250.0' "$PKG/visgrid-v17.lua"
grep -Fq 'v16TightPadding = 350.0' "$PKG/visgrid-v17.lua"

# Syntax-check Lua using whatever parser is installed on Ubuntu.
cat > "$PKG/parsecheck.lua" <<'EOF_PARSE'
local f=arg[1]
local c,e=loadfile(f)
if not c then error(e) end
print("PARSE PASS " .. f)
EOF_PARSE
if command -v luac >/dev/null 2>&1; then
    luac -p "$PKG/visgrid-v17.lua"
elif command -v lua >/dev/null 2>&1; then
    lua "$PKG/parsecheck.lua" "$PKG/visgrid-v17.lua"
elif command -v luatex >/dev/null 2>&1; then
    luatex --luaonly "$PKG/parsecheck.lua" "$PKG/visgrid-v17.lua"
else
    echo "NOTE: no host Lua parser; exact SHA/markers still verified."
fi

python3 -m py_compile "$PKG/tsp_patch_visgrid_v17_pvs.py"
echo "PASS: V17 Lua + source patcher verified."

echo
echo "===== 2/10 VERIFY CONTAINER + DEVICE BEFORE SOURCE EDIT ====="

if ! docker inspect "$CTR" >/dev/null 2>&1; then
    echo "ERROR: Docker container '$CTR' does not exist."
    exit 20
fi
if [ "$(docker inspect -f '{{.State.Running}}' "$CTR")" != "true" ]; then
    docker start "$CTR" >/dev/null
fi
docker exec "$CTR" test -d "$SRC"
docker exec "$CTR" test -d "$BUILD"

if ssh "${SSH[@]}" "$DEV"     'pidof openmw-0.51 >/dev/null 2>&1 || pidof openmw >/dev/null 2>&1'
then
    echo "ERROR: OpenMW is running. Exit normally, then rerun this SAME installer."
    exit 21
fi

ssh "${SSH[@]}" "$DEV" "
  set -e
  test -s '$BIN'
  test -s '$LUA'
  test -s '$TOPO'
  grep -a -q 'TSP_INTERIOR_VISGRID_051_V1' '$BIN'
  grep -Fq 'TSP_VISGRID_TOPOLOGY_V1' '$TOPO'
"

BIN_SHA_BEFORE="$(ssh "${SSH[@]}" "$DEV" "sha256sum '$BIN'" | awk '{print $1}')"
LUA_SHA_BEFORE="$(ssh "${SSH[@]}" "$DEV" "sha256sum '$LUA'" | awk '{print $1}')"
TOPO_SHA_BEFORE="$(ssh "${SSH[@]}" "$DEV" "sha256sum '$TOPO'" | awk '{print $1}')"

echo "Device binary  : $BIN_SHA_BEFORE"
echo "Device sensor  : $LUA_SHA_BEFORE"
echo "Device topology: $TOPO_SHA_BEFORE"

if [ "$TOPO_SHA_BEFORE" != "$TOPO_SHA" ]; then
    echo "ERROR: Governor's Hall topology differs from the tested V1 topology. ZERO edits."
    exit 22
fi
if [ "$LUA_SHA_BEFORE" != "$V16_SHA" ] && [ "$LUA_SHA_BEFORE" != "$V17_SHA" ]; then
    echo "ERROR: device sensor is neither exact V16 nor this exact V17. ZERO edits."
    exit 23
fi
if [ "$BIN_SHA_BEFORE" != "$BASE_BIN_SHA" ]; then
    if ! ssh "${SSH[@]}" "$DEV"         "grep -a -q 'TSP_INTERIOR_VISGRID_051_V5_TOPO_PVS' '$BIN'"
    then
        echo "ERROR: device binary is neither exact V16 base nor a V17-PVS binary. ZERO edits."
        exit 24
    fi
fi

echo "PASS: device state is known."

echo
echo "===== 3/10 VERIFY + BACK UP + PATCH SOURCE TRANSACTIONALLY ====="

docker cp "$PKG/tsp_patch_visgrid_v17_pvs.py" "$CTR:/tmp/tsp_patch_visgrid_v17_pvs.py"

set +e
PATCH_OUT="$(docker exec "$CTR" python3 /tmp/tsp_patch_visgrid_v17_pvs.py "$SRC_BACKUP" 2>&1)"
PATCH_RC=$?
set -e
printf '%s\n' "$PATCH_OUT" | tee "$PKG/source-patch.log"

if [ "$PATCH_RC" -ne 0 ]; then
    if docker exec "$CTR" test -d "$SRC_BACKUP" 2>/dev/null; then
        echo "Patch failed after backup creation; restoring source before stopping."
        restore_source
    fi
    exit "$PATCH_RC"
fi

if printf '%s\n' "$PATCH_OUT" | grep -Fq 'SOURCE_STATE=V17_PATCHED'; then
    PATCH_NEW=1
    PATCH_STARTED=1
elif printf '%s\n' "$PATCH_OUT" | grep -Fq 'SOURCE_STATE=V17_ALREADY_PATCHED'; then
    PATCH_NEW=0
else
    echo "ERROR: source patcher returned no recognized source state."
    exit 25
fi

echo "PASS: V17 source state verified."

echo
echo "===== 4/10 INCREMENTAL REBUILD ====="

PREBUILD_SHA=""
if docker exec "$CTR" test -s "$BUILT_BIN"; then
    PREBUILD_SHA="$(docker exec "$CTR" sha256sum "$BUILT_BIN" | awk '{print $1}')"
fi
echo "Pre-build SHA: $PREBUILD_SHA"

if docker exec "$CTR" bash -lc "
  test -s '$BUILT_BIN' &&
  file '$BUILT_BIN' | grep -Eqi 'aarch64' &&
  grep -a -q 'TSP_INTERIOR_VISGRID_051_V1' '$BUILT_BIN' &&
  grep -a -q 'TSP_INTERIOR_VISGRID_051_V3_PERCENTILE_FOG' '$BUILT_BIN' &&
  grep -a -q 'TSP_INTERIOR_VISGRID_051_V5_TOPO_PVS' '$BUILT_BIN'
"; then
    echo "PASS: existing V17 binary already built; skipping redundant rebuild."
    BUILD_RC=0

    # Prevent the later "source changed but binary SHA did not"
    # check from mistaking intentional reuse for a failed rebuild.
    PREBUILD_SHA=""
else
    echo "Existing Docker binary is not a complete V17 build; rebuilding incrementally."
    set +e
    docker exec "$CTR" bash -lc         "cmake --build '$BUILD' --target openmw -j2"         > >(tee "$PKG/build.log") 2>&1
    BUILD_RC=$?
    set -e
fi

if [ "$BUILD_RC" -ne 0 ]; then
    echo "ERROR: V17 incremental build failed."
    if [ "$PATCH_NEW" = 1 ]; then
        restore_source
    fi
    exit "$BUILD_RC"
fi

docker exec "$CTR" test -s "$BUILT_BIN"
NEW_BIN_SHA="$(docker exec "$CTR" sha256sum "$BUILT_BIN" | awk '{print $1}')"
echo "Post-build SHA: $NEW_BIN_SHA"

if [ "$PATCH_NEW" = 1 ] && [ -n "$PREBUILD_SHA" ] && [ "$NEW_BIN_SHA" = "$PREBUILD_SHA" ]; then
    echo "ERROR: source changed but built binary SHA did not."
    restore_source
    exit 26
fi

docker exec "$CTR" bash -lc "
  set -e
  file '$BUILT_BIN'
  file '$BUILT_BIN' | grep -Eqi 'aarch64'
  grep -a -q 'TSP_INTERIOR_VISGRID_051_V1' '$BUILT_BIN'
  grep -a -q 'TSP_INTERIOR_VISGRID_051_V3_PERCENTILE_FOG' '$BUILT_BIN'
  grep -a -q 'TSP_INTERIOR_VISGRID_051_V5_TOPO_PVS' '$BUILT_BIN'
"
BUILD_OK=1
echo "PASS: genuine AArch64 V17-PVS binary built."

echo
echo "===== 5/10 COPY VERIFIED BINARY OUT TO UBUNTU ====="

docker cp "$CTR:$BUILT_BIN" "$PKG/openmw-0.51-v17-pvs"
test -s "$PKG/openmw-0.51-v17-pvs"
test "$(sha256sum "$PKG/openmw-0.51-v17-pvs" | awk '{print $1}')" = "$NEW_BIN_SHA"
chmod +x "$PKG/openmw-0.51-v17-pvs"
echo "PASS: Docker -> Ubuntu binary SHA verified."

echo
echo "===== 6/10 BACK UP EXACT DEVICE BINARY + SENSOR ====="

REMOTE_BACKUP="$ROOT/backups/visgrid-v17-pvs-$STAMP"

ssh "${SSH[@]}" "$DEV" "
  set -e
  mkdir -p '$REMOTE_BACKUP'
  cp -p '$BIN' '$REMOTE_BACKUP/openmw-0.51.before-v17'
  cp -p '$LUA' '$REMOTE_BACKUP/visgrid.lua.before-v17'
  cp -p '$TOPO' '$REMOTE_BACKUP/topology.lua.before-v17'
  cmp -s '$BIN' '$REMOTE_BACKUP/openmw-0.51.before-v17'
  cmp -s '$LUA' '$REMOTE_BACKUP/visgrid.lua.before-v17'
  cmp -s '$TOPO' '$REMOTE_BACKUP/topology.lua.before-v17'
  sha256sum '$BIN' '$LUA' '$TOPO' > '$REMOTE_BACKUP/SHA256SUMS.before.txt'
  sync
"

scp "${SSH[@]}" -q "$DEV:$REMOTE_BACKUP/openmw-0.51.before-v17" "$PKG/device-backup/"
scp "${SSH[@]}" -q "$DEV:$REMOTE_BACKUP/visgrid.lua.before-v17" "$PKG/device-backup/"
scp "${SSH[@]}" -q "$DEV:$REMOTE_BACKUP/topology.lua.before-v17" "$PKG/device-backup/"
scp "${SSH[@]}" -q "$DEV:$REMOTE_BACKUP/SHA256SUMS.before.txt" "$PKG/device-backup/"

test "$(sha256sum "$PKG/device-backup/openmw-0.51.before-v17" | awk '{print $1}')" = "$BIN_SHA_BEFORE"
test "$(sha256sum "$PKG/device-backup/visgrid.lua.before-v17" | awk '{print $1}')" = "$LUA_SHA_BEFORE"
test "$(sha256sum "$PKG/device-backup/topology.lua.before-v17" | awk '{print $1}')" = "$TOPO_SHA_BEFORE"

echo "PASS: exact device backup verified on device + Ubuntu."

echo
echo "===== 7/10 STAGE + VERIFY BEFORE REPLACEMENT ====="

scp "${SSH[@]}" -q "$PKG/openmw-0.51-v17-pvs" "$DEV:/tmp/openmw-0.51-v17-pvs"
scp "${SSH[@]}" -q "$PKG/visgrid-v17.lua" "$DEV:/tmp/visgrid-v17.lua"

STAGE_BIN_SHA="$(ssh "${SSH[@]}" "$DEV" "sha256sum /tmp/openmw-0.51-v17-pvs" | awk '{print $1}')"
STAGE_LUA_SHA="$(ssh "${SSH[@]}" "$DEV" "sha256sum /tmp/visgrid-v17.lua" | awk '{print $1}')"
[ "$STAGE_BIN_SHA" = "$NEW_BIN_SHA" ]
[ "$STAGE_LUA_SHA" = "$V17_SHA" ]

ssh "${SSH[@]}" "$DEV" "
  grep -a -q 'TSP_INTERIOR_VISGRID_051_V5_TOPO_PVS' /tmp/openmw-0.51-v17-pvs
  grep -Fq 'TSP_VISGRID_LUA_V17_NAVMESH_PVS' /tmp/visgrid-v17.lua
  grep -Fq 'POST_LOAD_ARM_DELAY = 6.0' /tmp/visgrid-v17.lua
"
echo "PASS: staged binary + Lua verified."

echo
echo "===== 8/10 TRANSACTIONAL DEVICE INSTALL ====="

DEPLOY_STARTED=1

ssh "${SSH[@]}" "$DEV" "
  set -e
  cp /tmp/openmw-0.51-v17-pvs '$BIN.new'
  chmod +x '$BIN.new'
  mv -f '$BIN.new' '$BIN'

  cp /tmp/visgrid-v17.lua '$LUA.new'
  mv -f '$LUA.new' '$LUA'

  rm -f /tmp/openmw-0.51-v17-pvs /tmp/visgrid-v17.lua
  sync
"

INST_BIN_SHA="$(ssh "${SSH[@]}" "$DEV" "sha256sum '$BIN'" | awk '{print $1}')"
INST_LUA_SHA="$(ssh "${SSH[@]}" "$DEV" "sha256sum '$LUA'" | awk '{print $1}')"
INST_TOPO_SHA="$(ssh "${SSH[@]}" "$DEV" "sha256sum '$TOPO'" | awk '{print $1}')"

[ "$INST_BIN_SHA" = "$NEW_BIN_SHA" ]
[ "$INST_LUA_SHA" = "$V17_SHA" ]
[ "$INST_TOPO_SHA" = "$TOPO_SHA_BEFORE" ]

ssh "${SSH[@]}" "$DEV" "
  set -e
  grep -a -q 'TSP_INTERIOR_VISGRID_051_V5_TOPO_PVS' '$BIN'
  grep -Fq 'TSP_VISGRID_LUA_V17_NAVMESH_PVS' '$LUA'
  grep -Fq 'TSP_VISGRID_V17_LOADSAFE_6S' '$LUA'
  grep -Fq 'POST_LOAD_ARM_DELAY = 6.0' '$LUA'
  grep -Fq 'v16TightPadding = 350.0' '$LUA'
"

DEPLOY_STARTED=0
echo "PASS: V17 installed and SHA verified end-to-end."

echo
echo "===== 9/10 WRITE PULL + ROLLBACK DIRECTLY IN ~/Downloads ====="

cat > "$HOME/Downloads/pull-visgrid-v17-pvs.sh" <<'EOF_PULL'
#!/usr/bin/env bash
set -Eeuo pipefail

ROOT="/mnt/SDCARD/data/ports/openmw51"
TOOLS_OLD="$HOME/Downloads/visgrid-tools"

# Reuse an old device.env if it exists, but this helper itself lives directly
# in ~/Downloads and writes its output directly there.
if [ -f "$TOOLS_OLD/device.env" ]; then
    # shellcheck disable=SC1090
    . "$TOOLS_OLD/device.env" || true
fi

if [ -n "${TSP_DEV:-}" ]; then
    DEV="$TSP_DEV"
elif [ -n "${TSP_IP:-}" ]; then
    DEV="root@$TSP_IP"
else
    DEV="root@192.168.1.25"
fi

SSH=(-o BatchMode=yes -o ConnectTimeout=8)
STAMP="$(date +%Y%m%d-%H%M%S)"
OUT="$HOME/Downloads/visgrid-v17-pvs-trace-$STAMP.txt"

{
    echo "=================================================================="
    echo "VISGRID V17 NAVMESH-PVS TRACE"
    echo "=================================================================="
    echo "Ubuntu date: $(date)"
    echo "Device: $DEV"
    echo

    ssh "${SSH[@]}" "$DEV" 'date; hostname'

    echo
    echo "===== V17 / VISGRID / LOAD / PVS ====="
    ssh "${SSH[@]}" "$DEV" "
      grep -hE \
        'TSP_VISGRID_V17|TSP_VISGRID_V11|TSP_INTERIOR_VISGRID_051_V5_TOPO_PVS|TSP_INTERIOR_VISGRID|TSP_LOAD_FREEZE|Lua.*ERROR|Lua.*error' \
        '$ROOT/openmw_051_log.txt' '$ROOT/config-0.51/openmw.log' \
        2>/dev/null | tail -4200 || true
    "

    echo
    echo "===== PERF ====="
    ssh "${SSH[@]}" "$DEV" "
      [ -f '$ROOT/openmw51_perf_latest.txt' ] &&
        tail -900 '$ROOT/openmw51_perf_latest.txt' || true
    "

    echo
    echo "===== INSTALLED HASHES ====="
    ssh "${SSH[@]}" "$DEV" "
      sha256sum \
        '$ROOT/bin/openmw-0.51' \
        '$ROOT/mods/TSPInteriorVisGrid/scripts/TSPInteriorVisGrid/visgrid.lua' \
        '$ROOT/mods/TSPInteriorVisGrid/scripts/TSPInteriorVisGrid/topology.lua' \
        2>/dev/null || true
    "

    echo
    echo "===== BINARY MARKERS ====="
    ssh "${SSH[@]}" "$DEV" "
      for m in \
        TSP_INTERIOR_VISGRID_051_V1 \
        TSP_INTERIOR_VISGRID_051_V3_PERCENTILE_FOG \
        TSP_INTERIOR_VISGRID_051_V4_CULLFOG \
        TSP_INTERIOR_VISGRID_051_V5_TOPO_PVS
      do
        if grep -a -q \"\$m\" '$ROOT/bin/openmw-0.51'; then
          echo \"YES \$m\"
        else
          echo \"no  \$m\"
        fi
      done
    "
} 2>&1 | tee "$OUT"

echo
echo "Saved directly in Downloads:"
echo "  $OUT"

EOF_PULL
chmod +x "$HOME/Downloads/pull-visgrid-v17-pvs.sh"
bash -n "$HOME/Downloads/pull-visgrid-v17-pvs.sh"

cat > "$HOME/Downloads/rollback-visgrid-v17-pvs.sh" <<'EOF_ROLL'
#!/usr/bin/env bash
set -Eeuo pipefail

ENV="$HOME/Downloads/v17-last-backup.env"
test -s "$ENV"
# shellcheck disable=SC1090
. "$ENV"

SSH=(-o BatchMode=yes -o ConnectTimeout=8)

if ssh "${SSH[@]}" "$DEV" \
    'pidof openmw-0.51 >/dev/null 2>&1 || pidof openmw >/dev/null 2>&1'
then
    echo "ERROR: exit OpenMW normally before rollback."
    exit 20
fi

ssh "${SSH[@]}" "$DEV" "
  set -e
  test -s '$REMOTE_BACKUP/openmw-0.51.before-v17'
  test -s '$REMOTE_BACKUP/visgrid.lua.before-v17'
  cp -p '$REMOTE_BACKUP/openmw-0.51.before-v17' '$BIN'
  cp -p '$REMOTE_BACKUP/visgrid.lua.before-v17' '$LUA'
  chmod +x '$BIN'
  sync
  sha256sum '$BIN' '$LUA'
"

echo "PASS: exact pre-V17 binary + sensor restored."

EOF_ROLL
chmod +x "$HOME/Downloads/rollback-visgrid-v17-pvs.sh"
bash -n "$HOME/Downloads/rollback-visgrid-v17-pvs.sh"

cat > "$HOME/Downloads/v17-last-backup.env" <<EOF_ENV
DEV=$(printf '%q' "$DEV")
REMOTE_BACKUP=$(printf '%q' "$REMOTE_BACKUP")
BIN=$(printf '%q' "$BIN")
LUA=$(printf '%q' "$LUA")
EOF_ENV

# Also preserve exact helper copies in the package.
cp -p "$HOME/Downloads/pull-visgrid-v17-pvs.sh" "$PKG/"
cp -p "$HOME/Downloads/rollback-visgrid-v17-pvs.sh" "$PKG/"
cp -p "$HOME/Downloads/v17-last-backup.env" "$PKG/"

echo "PASS: helper files exist DIRECTLY in Downloads:"
ls -l   "$HOME/Downloads/pull-visgrid-v17-pvs.sh"   "$HOME/Downloads/rollback-visgrid-v17-pvs.sh"

echo
echo "===== 10/10 WRITE HANDOFF ====="

cat > "$PKG/README-V17.txt" <<EOF_README
VISGRID V17 NAVMESH STRUCTURAL PVS
===================================

Device binary before:
  $BIN_SHA_BEFORE

Device sensor before:
  $LUA_SHA_BEFORE

V17 binary:
  $NEW_BIN_SHA

V17 Lua:
  $V17_SHA

Topology (unchanged):
  $TOPO_SHA_BEFORE

Source backup:
  $SRC_BACKUP

Device backup:
  $REMOTE_BACKUP

Runtime design:
  1. Navmesh topology selects a conservative structural candidate set.
  2. C++ PVS tests only immutable ESM::Static roots.
  3. If a static root overlaps any active sector, it stays.
  4. If it overlaps no mapped sector, it stays.
  5. Only a root overlapping mapped sectors EXCLUSIVELY outside the active
     PVS is rejected before LightList/state traversal.
  6. Existing 8x5 VISGRID then performs local camera-space depth culling.
  7. Actors, doors, dynamic objects and huge/ambiguous statics bypass PVS.
  8. Current floor is fully active; stair connectors retain both endpoints.
  9. Large-room portal traversal pre-opens a 3x7 screen wedge.
 10. Ordinary mapped door traversal pre-opens a 3x5 wedge.
 11. VISGRID padding is back to 350.
 12. Post-load/start safety hold remains exactly 6.0 seconds.

